import { defineStore } from 'pinia';
import {
  ExtensionParsingError,
  type Extension,
  type ExtensionManifest,
  type ExtensionMeta,
  type ExtensionSource,
  type ExtensionSourceInfo,
  type ExtensionStore,
  type GitRepoHandle,
  type GitSource,
  type LocalSource,
} from 'orgnote-api';
import { ref, computed } from 'vue';
import { api } from 'src/boot/api';
import { extensionTimer } from 'src/boot/perf-timer';
import { compileExtension, parseExtensionFromFile } from 'src/utils/read-extension';
import { validateManifest } from 'src/utils/validate-manifest';
import { reporter } from 'src/boot/report';
import { to } from 'orgnote-api/utils';
import { useFileSystemStore } from './file-system';
import { parseToml, stringifyToml } from 'orgnote-api/utils';
import { useGitStore } from './git';
import { resetCSSVariables } from 'src/utils/css-utils';
import { THEME_VARIABLES } from 'orgnote-api';
import { useConfigStore } from './config';
import { Dark } from 'quasar';
import { ORGNOTE_EXTENSIONS_FILE_PATH } from 'src/constants/system-file-paths';
import { BUILTIN_LOADERS, BUILTIN_META } from 'src/extensions';

interface ActiveExtension extends ExtensionMeta {
  module: Extension;
}

interface ExtensionsFile {
  extensions: ExtensionMeta[];
}

interface FetchedExtension {
  manifest: ExtensionManifest;
  module: string;
  rawContent: string;
}

type SourceFetcher = (source: ExtensionSourceInfo) => Promise<FetchedExtension>;

const extensionsFilePath = ORGNOTE_EXTENSIONS_FILE_PATH;
const distFolder = 'dist';

export const useExtensionsStore = defineStore<'extension', ExtensionStore>('extension', () => {
  const extensions = ref<ExtensionMeta[]>([]);
  const activeExtensions = ref<ActiveExtension[]>([]);
  const fileSystem = useFileSystemStore();

  const loading = ref<number>(0);
  const ready = computed(() => loading.value <= 0);

  const safeParseToml = to(parseToml, (e) => new SyntaxError('Invalid TOML format', { cause: e }));
  const safeStringifyToml = to(
    stringifyToml,
    (e) => new Error('Failed to stringify TOML', { cause: e }),
  );

  const sync = async (): Promise<void> => {
    loading.value++;

    try {
      await extensionTimer.measure('sync', async () => {
        await readFromDisk();
        registerBuiltinExtensions();
        await mountActiveExtensions();
      });
    } finally {
      loading.value--;
    }
  };

  const registerBuiltinExtensions = (): void => {
    BUILTIN_META.forEach((meta) => {
      const exists = extensions.value.some((e) => e.manifest.name === meta.manifest.name);
      if (!exists) {
        extensions.value.push(meta);
      }
    });
  };

  const writeToDisk = async (): Promise<void> => {
    const data: ExtensionsFile = { extensions: extensions.value };
    const safeWrite = to(fileSystem.writeFile, 'Failed to write extensions.toml');

    const res = safeStringifyToml(data).asyncAndThen((content) =>
      safeWrite(extensionsFilePath, content),
    );

    const result = await res;
    if (result.isErr()) {
      reporter.reportError(result.error);
    }
  };

  const readFromDisk = async (): Promise<void> => {
    const safeRead = to(fileSystem.readFile, 'Failed to read extensions.toml');

    const res = await safeRead(extensionsFilePath, 'utf8');

    if (res.isErr()) {
      return;
    }

    const content = res.value;
    if (!content) {
      return;
    }

    const parseResult = safeParseToml(content as string);
    if (parseResult.isErr()) {
      reporter.reportError(parseResult.error);
      return;
    }

    const data = parseResult.value as unknown as ExtensionsFile;
    extensions.value = data.extensions ?? [];
  };

  const mountActiveExtensions = async (): Promise<void> => {
    const activeExtensionsMeta = extensions.value.filter((meta) => meta.active);

    const mountPromises = activeExtensionsMeta.map((meta) => mountExtension(meta));

    await Promise.allSettled(mountPromises);
  };

  const compileFromRepository = async (name: string): Promise<Extension | undefined> => {
    const source = await api.infrastructure.extensionSourceRepository.get(name);
    if (!source) {
      return undefined;
    }

    const safeCompile = to(compileExtension, 'Failed to load extension');
    const compileResult = await safeCompile(source.module);

    if (compileResult.isErr()) {
      reporter.reportError(compileResult.error);
      return undefined;
    }

    return compileResult.value;
  };

  const getExtensionModule = (name: string): Promise<Extension | undefined> =>
    BUILTIN_LOADERS[name]?.() ?? compileFromRepository(name);

  const mountExtension = async (meta: ExtensionMeta): Promise<ActiveExtension | undefined> => {
    return extensionTimer.measure(`mount:${meta.manifest.name}`, async () => {
      const existingActive = activeExtensions.value.find(
        (e) => e.manifest.name === meta.manifest.name,
      );
      if (existingActive) {
        return existingActive;
      }

      const module = await getExtensionModule(meta.manifest.name);
      if (!module) {
        return undefined;
      }

      const safeMounted = to(
        module.onMounted.bind(module),
        `Failed to mount extension ${meta.manifest.name}`,
      );
      const mountResult = await safeMounted(api);

      if (mountResult.isErr()) {
        reporter.reportError(mountResult.error);
        return undefined;
      }

      const activeExt: ActiveExtension = {
        manifest: meta.manifest,
        active: true,
        config: meta.config,
        module,
      };

      activeExtensions.value.push(activeExt);
      return activeExt;
    });
  };

  const unmountExtension = async (extensionName: string): Promise<void> => {
    return extensionTimer.measure(`unmount:${extensionName}`, async () => {
      const ext = activeExtensions.value.find((e) => e.manifest.name === extensionName);
      if (!ext) {
        return;
      }

      if (ext.module?.onUnmounted) {
        const safeUnmount = to(
          ext.module.onUnmounted.bind(ext.module),
          'Failed to unmount extension',
        );
        const result = await safeUnmount(api);

        if (result.isErr()) {
          reporter.reportError(result.error);
        }
      }

      activeExtensions.value = activeExtensions.value.filter(
        (e) => e.manifest.name !== extensionName,
      );
    });
  };

  const isThemeExtension = (manifest: ExtensionManifest): boolean => {
    return (manifest.category ?? '').toLowerCase() === 'theme';
  };

  const disableOtherThemes = async (currentThemeName: string): Promise<void> => {
    const otherActiveThemes = extensions.value.filter(
      (e) => e.active && isThemeExtension(e.manifest) && e.manifest.name !== currentThemeName,
    );

    const unmountPromises = otherActiveThemes.map(async (theme) => {
      await unmountExtension(theme.manifest.name);
      theme.active = false;
    });

    await Promise.allSettled(unmountPromises);
  };

  const setConfigThemeName = (themeName: string | null): void => {
    const { config } = useConfigStore();
    if (Dark.isActive) {
      config.ui.darkThemeName = themeName;
      return;
    }
    config.ui.lightThemeName = themeName;
  };

  const handleThemeActivation = async (extensionName: string): Promise<void> => {
    await disableOtherThemes(extensionName);
    resetCSSVariables([...THEME_VARIABLES]);
    setConfigThemeName(extensionName);
  };

  const handleThemeDeactivation = (extensionName: string): void => {
    const { config } = useConfigStore();
    const isCurrentDarkTheme = Dark.isActive && config.ui.darkThemeName === extensionName;
    const isCurrentLightTheme = !Dark.isActive && config.ui.lightThemeName === extensionName;
    if (!isCurrentDarkTheme && !isCurrentLightTheme) {
      return;
    }
    resetCSSVariables([...THEME_VARIABLES]);
    setConfigThemeName(null);
  };

  const enableExtension = async (extensionName: string): Promise<void> => {
    const meta = extensions.value.find((e) => e.manifest.name === extensionName);
    if (!meta) {
      reporter.reportWarning(`Extension ${extensionName} not found`);
      return;
    }

    if (meta.active) {
      return;
    }

    if (isThemeExtension(meta.manifest)) {
      await handleThemeActivation(extensionName);
    }

    await mountExtension(meta);
    meta.active = true;
    await writeToDisk();
  };

  const disableExtension = async (extensionName: string): Promise<void> => {
    const meta = extensions.value.find((e) => e.manifest.name === extensionName);
    if (!meta) {
      reporter.reportWarning(`Extension ${extensionName} not found`);
      return;
    }

    if (isThemeExtension(meta.manifest)) {
      handleThemeDeactivation(extensionName);
    }

    await unmountExtension(extensionName);
    meta.active = false;
    await writeToDisk();
  };

  const isExtensionExist = (extensionName: string): boolean => {
    return !!extensions.value.find((e) => e.manifest.name === extensionName);
  };

  const addExtension = async (meta: ExtensionMeta, source: ExtensionSource): Promise<void> => {
    extensions.value = extensions.value.filter((e) => e.manifest.name !== meta.manifest.name);
    extensions.value.push(meta);

    const safeUpsert = to(
      api.infrastructure.extensionSourceRepository.upsert,
      'Failed to save extension source',
    );
    const upsertResult = await safeUpsert(source);

    if (upsertResult.isErr()) {
      reporter.reportError(upsertResult.error);
      return;
    }

    await writeToDisk();

    if (meta.active) {
      await enableExtension(meta.manifest.name);
    }
  };

  const resolveExtensionPaths = async (
    repoHandle: GitRepoHandle,
  ): Promise<{ entryPath: string; manifestPath: string }> => {
    const hasDist = await repoHandle.fileExists(distFolder);
    const baseDir = hasDist ? `${distFolder}/` : '';
    return {
      entryPath: `${baseDir}index.js`,
      manifestPath: `${baseDir}manifest.json`,
    };
  };

  const extractManifestFromModule = async (moduleContent: string): Promise<ExtensionManifest> => {
    const encodedModule = encodeURIComponent(moduleContent);
    const moduleUrl = `data:text/javascript,${encodedModule}`;
    const m = (await import(/* @vite-ignore */ moduleUrl)) as {
      manifest?: ExtensionManifest;
    };

    if (!m.manifest) {
      throw new Error('Extension manifest not found in module exports');
    }

    return m.manifest;
  };

  const parseManifestJson = (content: string): ExtensionManifest => JSON.parse(content);

  const resolveManifest = async (
    repoHandle: GitRepoHandle,
    manifestPath: string,
    moduleContent: string,
  ): Promise<ExtensionManifest> => {
    const hasManifest = await repoHandle.fileExists(manifestPath);

    if (!hasManifest) {
      const manifest = await extractManifestFromModule(moduleContent);
      validateManifest(manifest);
      return manifest;
    }

    const content = await repoHandle.readFile(manifestPath, 'utf8');
    const safeParse = to(parseManifestJson, `Invalid manifest JSON in ${manifestPath}`);
    const parseResult = safeParse(content);

    if (parseResult.isErr()) {
      throw parseResult.error;
    }

    validateManifest(parseResult.value);
    return parseResult.value;
  };

  const fetchFromGit = async (source: GitSource): Promise<FetchedExtension> => {
    const gitStore = useGitStore();
    const repoHandle = await gitStore.openRepo({
      url: source.repo,
      branch: source.branch ?? source.tag,
    });

    const paths = await resolveExtensionPaths(repoHandle);
    const moduleContent = await repoHandle.readFile(paths.entryPath, 'utf8');
    const manifest = await resolveManifest(repoHandle, paths.manifestPath, moduleContent);
    manifest.source = source;

    return {
      manifest,
      module: encodeURIComponent(moduleContent),
      rawContent: moduleContent,
    };
  };

  const sourceFetchers: Record<ExtensionSourceInfo['type'], SourceFetcher> = {
    git: (source) => fetchFromGit(source as GitSource),
    local: () => {
      throw new Error('Local extensions cannot be installed via installExtension');
    },
    builtin: () => {
      throw new Error('Builtin extensions cannot be installed via installExtension');
    },
  };

  const installExtension = async (source: ExtensionSourceInfo): Promise<void> => {
    const fetcher = sourceFetchers[source.type];

    const safeFetch = to(fetcher, 'Failed to fetch extension');
    const fetchResult = await safeFetch(source);

    if (fetchResult.isErr()) {
      reporter.reportError(fetchResult.error);
      return;
    }

    const fetched = fetchResult.value;

    const meta: ExtensionMeta = {
      manifest: fetched.manifest,
      active: true,
    };

    const extensionSource: ExtensionSource = {
      name: fetched.manifest.name,
      version: fetched.manifest.version,
      source: source.type === 'git' ? (source as GitSource).repo : 'local',
      module: fetched.module,
      docFiles: [],
    };

    await addExtension(meta, extensionSource);
  };

  const deleteExtension = async (extensionName: string): Promise<void> => {
    await unmountExtension(extensionName);

    const safeDelete = to(
      api.infrastructure.extensionSourceRepository.delete,
      'Failed to delete extension source',
    );
    const deleteResult = await safeDelete(extensionName);

    if (deleteResult.isErr()) {
      reporter.reportError(deleteResult.error);
    }

    extensions.value = extensions.value.filter((e) => e.manifest.name !== extensionName);
    await writeToDisk();
  };

  const importExtension = async (file: File): Promise<void> => {
    const safeParse = to(parseExtensionFromFile, (e: unknown) => {
      const error = e instanceof Error ? e : new Error(String(e));
      return new ExtensionParsingError(file.name, { cause: error });
    });
    const parseResult = await safeParse(file);

    if (parseResult.isErr()) {
      reporter.reportError(parseResult.error);
      return;
    }

    const { manifest, rawContent } = parseResult.value;

    const localSource: LocalSource = { type: 'local' };
    manifest.source = localSource;
    manifest.development = true;

    const meta: ExtensionMeta = {
      manifest,
      active: true,
      uploaded: true,
    };

    const extensionSource: ExtensionSource = {
      name: manifest.name,
      version: manifest.version,
      source: 'local',
      module: rawContent,
      docFiles: [],
    };

    await addExtension(meta, extensionSource);
  };

  const enableSafeMode = async (): Promise<void> => {
    const nonLocalExtensions = activeExtensions.value.filter(
      (ext) => ext.manifest.source.type !== 'local',
    );

    const unmountPromises = nonLocalExtensions.map((ext) => unmountExtension(ext.manifest.name));
    await Promise.allSettled(unmountPromises);
  };

  const disableSafeMode = async (): Promise<void> => {
    const activeExtensionsMeta = extensions.value.filter((meta) => meta.active);
    const mountPromises = activeExtensionsMeta.map((meta) => mountExtension(meta));
    await Promise.allSettled(mountPromises);
  };

  const store: ExtensionStore = {
    extensions,
    ready,

    sync,
    enableExtension,
    disableExtension,
    isExtensionExist,
    addExtension,
    installExtension,
    importExtension,
    deleteExtension,
    enableSafeMode,
    disableSafeMode,
  };

  return store;
});

import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import type { SyncStore, SyncPlan, SyncStateData, FileSystem } from 'orgnote-api';
import { createSyncPlan, recoverState } from 'orgnote-api';
import { reporter } from 'src/boot/report';
import { sdk } from 'src/boot/axios';
import { createSyncState } from 'src/utils/sync-state';
import { to } from 'orgnote-api/utils';
import { enqueuePlanOperations, isPlanEmpty } from 'src/infrastructure/sync';
import { useFileSystemManagerStore } from './file-system-manager';
import { api } from 'src/boot/api';
import axios from 'axios';

const httpUpgradeRequired = 426;
const rootPath = '/';
const contentHashCheckEnabled = true;

export const useSyncStore = defineStore<'sync', SyncStore>(
  'sync',
  (): SyncStore => {
    const currentPlan = ref<SyncPlan | null>(null);
    const stateData = ref<SyncStateData | null>({ files: {} });
    const isVersionIncompatible = ref(false);

    const state = createSyncState(stateData);
    const fs = computed(() => useFileSystemManagerStore().currentFs as FileSystem);

    const isSyncProhibited = (): boolean => {
      const authStore = api.core.useAuth();
      const configStore = api.core.useConfig();
      return (
        isVersionIncompatible.value ||
        !authStore.user?.active ||
        configStore.config.synchronization.type === 'none'
      );
    };

    const isVersionError = (error: Error): boolean => {
      return axios.isAxiosError(error) && error.response?.status === httpUpgradeRequired;
    };

    const handleSyncError = (error: Error): null => {
      if (isVersionError(error)) {
        isVersionIncompatible.value = true;
        return null;
      }

      reporter.reportError(error);
      return null;
    };

    const createPlanAction = async (): Promise<SyncPlan | null> => {
      const recoverResult = await to(recoverState)(state);
      if (recoverResult.isErr()) return handleSyncError(recoverResult.error);

      const planResult = await to(createSyncPlan)({
        fs: fs.value,
        api: sdk.sync,
        state,
        rootPath: rootPath,
        enableContentHashCheck: contentHashCheckEnabled,
      });
      if (planResult.isErr()) return handleSyncError(planResult.error);

      currentPlan.value = planResult.value;
      return planResult.value;
    };

    const executePlan = async (plan: SyncPlan): Promise<void> => {
      enqueuePlanOperations(plan);
      currentPlan.value = null;
    };

    const sync = async (): Promise<void> => {
      if (isSyncProhibited()) {
        return;
      }

      const plan = await createPlanAction();

      if (!plan) {
        return;
      }

      if (isPlanEmpty(plan)) {
        return;
      }

      await executePlan(plan);
    };

    const reset = async (): Promise<void> => {
      await state.clear();
      currentPlan.value = null;
    };

    return {
      currentPlan,
      stateData,
      createPlan: createPlanAction,
      executePlan,
      sync,
      reset,
    };
  },
  {
    persist: {
      pick: ['stateData'],
    },
  },
);

import {
  DefaultCommands,
  I18N,
  RouteNames,
  getFileName,
  join,
  type Command,
  type CommandHandlerParams,
  type FileSortConfig,
  type OrgNoteApi,
  type PendingFileOperation,
} from 'orgnote-api';
import { reporter } from 'src/boot/report';
import { createFileCompletion } from 'src/composables/create-file-completion';
import { createFolderCompletion } from 'src/composables/create-folder-completion';
import { deleteFileCompletion } from 'src/composables/delete-file-completion';
import { useFileRenameCompletion } from 'src/composables/file-rename-completion';
import { getFileDirPath } from 'src/utils/get-file-dir-path';
import { to } from 'orgnote-api/utils';
import { defineAsyncComponent } from 'vue';
import { buildSortCandidates } from 'src/composables/sort-files-completion';
import { getActiveFilePath } from 'src/utils/get-active-file-path';
import {
  useTransferDestinationCompletion,
  type TransferDestination,
} from 'src/composables/transfer-destination-completion';

const group = 'file manager';

type FileTargetsCommandData = {
  path?: string;
  paths?: string[];
  interactive?: boolean;
};

type DeleteFileCommandData = FileTargetsCommandData & {
  force?: boolean;
};

const getTargetPathsFromCommandData = (data?: FileTargetsCommandData): string[] | undefined => {
  if (data?.paths?.length) {
    return data.paths;
  }

  if (data?.path) {
    return [data.path];
  }
};

const cancelAndThrow = (fm: ReturnType<OrgNoteApi['core']['useFileManager']>, error: Error): never => {
  fm.cancelPending();
  throw error;
};

const pickInteractiveDestination = async (
  api: OrgNoteApi,
  fm: ReturnType<OrgNoteApi['core']['useFileManager']>,
): Promise<TransferDestination | undefined> => {
  const destinationResult = await to(
    useTransferDestinationCompletion,
    'Failed to pick destination',
  )(api, fm.path);

  if (destinationResult.isErr()) {
    return cancelAndThrow(fm, destinationResult.error);
  }

  const destination = destinationResult.value;
  if (!destination) {
    fm.cancelPending();
    return;
  }

  return destination;
};

const executeExplicitTransferIfRequired = async (
  api: OrgNoteApi,
  fm: ReturnType<OrgNoteApi['core']['useFileManager']>,
  pendingOperation: PendingFileOperation | undefined,
  destination: TransferDestination,
): Promise<boolean> => {
  const explicitTransferResult = await to(
    executeExplicitTransfer,
    'Failed to execute pending transfer',
  )(api, pendingOperation, destination);

  if (explicitTransferResult.isErr()) {
    return cancelAndThrow(fm, explicitTransferResult.error);
  }

  if (!explicitTransferResult.value) {
    return false;
  }

  fm.cancelPending();
  return true;
};

const executePendingTransferAndSync = async (
  api: OrgNoteApi,
  fm: ReturnType<OrgNoteApi['core']['useFileManager']>,
  pendingOperation: PendingFileOperation | undefined,
  destination: TransferDestination,
): Promise<void> => {
  const executeResult = await to(
    fm.executePending.bind(fm),
    'Failed to execute pending transfer',
  )(destination.destinationDir);

  if (executeResult.isErr()) {
    return cancelAndThrow(fm, executeResult.error);
  }

  await safeSyncActiveFileAfterMove(api, pendingOperation, destination.destinationDir);
};

const executeInteractiveTransfer = async (
  api: OrgNoteApi,
  pendingOperation: PendingFileOperation | undefined,
): Promise<void> => {
  const fm = api.core.useFileManager();
  const destination = await pickInteractiveDestination(api, fm);
  if (!destination) {
    return;
  }

  const handledByExplicitTransfer = await executeExplicitTransferIfRequired(
    api,
    fm,
    pendingOperation,
    destination,
  );
  if (handledByExplicitTransfer) {
    return;
  }

  await executePendingTransferAndSync(api, fm, pendingOperation, destination);
};

const canTransferToExplicitPath = (
  operation: PendingFileOperation | undefined,
  destination: TransferDestination,
): operation is PendingFileOperation => {
  if (!operation?.paths.length || !destination.explicitFilePath) {
    return false;
  }

  return operation.paths.length === 1;
};

const executeExplicitTransfer = async (
  api: OrgNoteApi,
  operation: PendingFileOperation | undefined,
  destination: TransferDestination,
): Promise<boolean> => {
  if (!canTransferToExplicitPath(operation, destination)) {
    return false;
  }

  const sourcePath = operation.paths[0]!;
  const targetPath = destination.explicitFilePath!;
  const fs = api.core.useFileSystem();
  const transfer = operation.type === 'copy' ? fs.copyFile.bind(fs) : fs.rename.bind(fs);

  const transferResult = await to(transfer, 'Failed to execute pending transfer')(
    sourcePath,
    targetPath,
  );
  if (transferResult.isErr()) {
    throw transferResult.error;
  }

  if (operation.type === 'move') {
    await safeSyncActiveFileAfterRename(api, sourcePath, targetPath);
  }

  return true;
};

const toPathPrefix = (path: string): string => (path.endsWith('/') ? path : `${path}/`);

const remapPath = (
  activePath: string,
  previousPath: string,
  nextPath: string,
): string | undefined => {
  if (activePath === previousPath) {
    return nextPath;
  }

  const previousPrefix = toPathPrefix(previousPath);
  if (!activePath.startsWith(previousPrefix)) {
    return;
  }

  return `${nextPath}${activePath.slice(previousPath.length)}`;
};

const reopenPath = async (api: OrgNoteApi, path: string): Promise<void> => {
  const panes = api.core.usePane();
  const activeTab = panes.activeTab;
  if (activeTab?.router) {
    await activeTab.router.replace({
      name: RouteNames.File,
      params: {
        paneId: activeTab.paneId,
        path,
      },
    });
    return;
  }

  const commands = api.core.useCommands();
  await commands.execute(DefaultCommands.OPEN_NOTE, { path });
};

const syncActiveFileAfterRename = async (
  api: OrgNoteApi,
  previousPath: string,
  nextPath: string,
): Promise<void> => {
  const activePath = getActiveFilePath(api);
  if (!activePath) {
    return;
  }

  const remappedPath = remapPath(activePath, previousPath, nextPath);
  if (!remappedPath) {
    return;
  }

  await reopenPath(api, remappedPath);
};

const safeSyncActiveFileAfterRename = async (
  api: OrgNoteApi,
  previousPath: string,
  nextPath: string,
): Promise<void> => {
  const syncResult = await to(syncActiveFileAfterRename, 'Failed to sync active file after rename')(
    api,
    previousPath,
    nextPath,
  );

  if (syncResult.isErr()) {
    reporter.reportWarning(syncResult.error);
  }
};

const getMoveDestinationPath = (sourcePath: string, destinationDir: string): string =>
  join(destinationDir, getFileName(sourcePath));

const syncActiveFileAfterMove = async (
  api: OrgNoteApi,
  operation: PendingFileOperation | undefined,
  destinationDir: string,
): Promise<void> => {
  if (!operation || operation.type !== 'move') {
    return;
  }

  const activePath = getActiveFilePath(api);
  if (!activePath) {
    return;
  }

  const remappedPath = operation.paths
    .map((sourcePath) => {
      const destinationPath = getMoveDestinationPath(sourcePath, destinationDir);
      return remapPath(activePath, sourcePath, destinationPath);
    })
    .find((path) => !!path);

  if (!remappedPath) {
    return;
  }

  await reopenPath(api, remappedPath);
};

const safeSyncActiveFileAfterMove = async (
  api: OrgNoteApi,
  operation: PendingFileOperation | undefined,
  destinationDir: string,
): Promise<void> => {
  const syncResult = await to(syncActiveFileAfterMove, 'Failed to sync active file after move')(
    api,
    operation,
    destinationDir,
  );

  if (syncResult.isErr()) {
    reporter.reportWarning(syncResult.error);
  }
};

const createTransferHandler =
  (startOperation: (api: OrgNoteApi, targets: string[]) => void) =>
  async (api: OrgNoteApi, params?: CommandHandlerParams<FileTargetsCommandData>): Promise<void> => {
    const fm = api.core.useFileManager();
    const targets = getTargetPathsFromCommandData(params?.data) ?? fm.operationTargets;
    if (!targets.length) return;

    startOperation(api, targets);

    if (!params?.data?.interactive) {
      return;
    }

    await executeInteractiveTransfer(api, fm.pendingOperation);
  };

export function getFileManagerCommands(): Command[] {
  const commands: Command[] = [
    {
      command: DefaultCommands.MAXIMIZE_FILE_MANAGER,
      group,
      icon: 'sym_o_fit_screen',
      handler: (api: OrgNoteApi) => {
        const modal = api.ui.useModal();
        modal.open(
          defineAsyncComponent(() => import('src/containers/FileManager.vue')),
          {
            modalProps: {
              closable: true,
            },
            modalEmits: {
              close: () => modal.close(),
            },
          },
        );
      },
    },
    {
      command: DefaultCommands.TOGGLE_FILE_MANAGER,
      group,
      icon: 'folder',
      handler: (api: OrgNoteApi) => {
        const sidebar = api.ui.useSidebar();
        if (sidebar.opened) {
          sidebar.close();
          return;
        }
        sidebar.openComponent(
          defineAsyncComponent(() => import('src/containers/FileManager.vue')),
          {
            componentProps: {
              closable: false,
              tree: true,
              compact: true,
            },
          },
        );
      },
    },
    {
      command: DefaultCommands.CREATE_FOLDER,
      group,
      icon: 'sym_o_create_new_folder',
      handler: async (api: OrgNoteApi) => {
        const res = await to(createFolderCompletion, 'Failed to create folder')(api);
        if (res.isErr()) {
          reporter.reportError(res.error);
        }
      },
    },
    {
      command: DefaultCommands.CREATE_NOTE,
      group: 'file manager',
      icon: 'o_add_box',
      handler: async (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        const filePath = await createFileCompletion(api);
        if (!filePath) {
          return;
        }
        const dirPath = getFileDirPath(filePath);
        fm.path = dirPath;

        const commands = api.core.useCommands();
        await commands.execute(DefaultCommands.OPEN_NOTE, { path: filePath });
      },
    },
    {
      command: DefaultCommands.RENAME_FILE,
      group,
      icon: 'sym_o_edit',
      handler: async (api: OrgNoteApi, params: CommandHandlerParams<FileTargetsCommandData>) => {
        const fm = api.core.useFileManager();
        const targetPath = params?.data?.path ?? fm.focusFile?.path;
        if (!targetPath) {
          return;
        }
        const nextPath = await useFileRenameCompletion(api, targetPath);
        if (!nextPath) {
          return;
        }
        await syncActiveFileAfterRename(api, targetPath, nextPath);
      },
    },
    {
      command: DefaultCommands.SHOW_MOBILE_FILE_SEARCH,
      group,
      icon: 'search',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        fm.mobileFileSearchActive = true;
      },
      hide: (api: OrgNoteApi) => !api.ui.useScreenDetection().tabletBelow.value,
    },
    {
      command: DefaultCommands.HIDE_MOBILE_FILE_SEARCH,
      group,
      icon: 'close',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        fm.mobileFileSearchActive = false;
        fm.searchQuery = '';
      },
      hide: (api: OrgNoteApi) => !api.ui.useScreenDetection().tabletBelow.value,
    },
    {
      command: DefaultCommands.DELETE_FILE,
      group,
      icon: 'sym_o_delete',
      handler: async (api: OrgNoteApi, params: CommandHandlerParams<DeleteFileCommandData>) => {
        const fm = api.core.useFileManager();
        const paths = getTargetPathsFromCommandData(params?.data);
        const targets = paths ?? fm.operationTargets;

        if (!targets.length) {
          await deleteFileCompletion(api);
          return;
        }

        if (params?.data?.force) {
          const fs = api.core.useFileSystem();
          await Promise.all(targets.map((p) => fs.deleteFile(p)));
          fm.clearSelection();
          return;
        }

        return deleteWithConfirmation(api, targets);
      },
    },
    {
      command: DefaultCommands.COPY_FILE,
      group,
      icon: 'sym_o_content_copy',
      handler: createTransferHandler((api, targets) =>
        api.core.useFileManager().startCopy(targets),
      ),
    },
    {
      command: DefaultCommands.MOVE_FILE,
      group,
      icon: 'sym_o_drive_file_move',
      handler: createTransferHandler((api, targets) =>
        api.core.useFileManager().startMove(targets),
      ),
    },
    {
      command: DefaultCommands.EXECUTE_PENDING_FILE_OPERATION,
      group,
      icon: 'sym_o_content_paste',
      handler: async (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        const pendingOperation = fm.pendingOperation;
        await fm.executePending(fm.path);
        await safeSyncActiveFileAfterMove(api, pendingOperation, fm.path);
      },
    },
    {
      command: DefaultCommands.CANCEL_PENDING_FILE_OPERATION,
      group,
      icon: 'close',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        fm.cancelPending();
      },
    },
    {
      command: DefaultCommands.SELECT_FILE,
      group,
      icon: 'sym_o_check_circle',
      handler: (api: OrgNoteApi, params: CommandHandlerParams<FileTargetsCommandData>) => {
        const fm = api.core.useFileManager();
        const targetPath = params?.data?.path ?? fm.focusFile?.path;
        if (!targetPath) return;

        fm.toggleSelection(targetPath);
      },
    },
    {
      command: DefaultCommands.SELECT_ALL_FILES,
      group,
      icon: 'sym_o_select_all',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        fm.selectFiles([...fm.files]);
      },
    },
    {
      command: DefaultCommands.DESELECT_ALL_FILES,
      group,
      icon: 'sym_o_deselect',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        fm.clearSelection();
      },
    },
    {
      command: DefaultCommands.REVEAL_IN_FILE_MANAGER,
      group,
      icon: 'sym_o_my_location',
      handler: (api: OrgNoteApi) => {
        const filePath = getActiveFilePath(api);
        if (!filePath) return;
        const fm = api.core.useFileManager();
        fm.path = getFileDirPath(filePath);
        const sidebar = api.ui.useSidebar();
        if (!sidebar.opened) {
          sidebar.openComponent(
            defineAsyncComponent(() => import('src/containers/FileManager.vue')),
            {
              componentProps: {
                closable: false,
                tree: true,
                compact: true,
              },
            },
          );
        }
      },
    },
    {
      command: DefaultCommands.SORT_FILES,
      group,
      icon: 'sym_o_sort',
      handler: (api: OrgNoteApi) => {
        const fm = api.core.useFileManager();
        const completion = api.core.useCompletion();

        completion.open<FileSortConfig>({
          placeholder: I18N.SORT_FILES,
          type: 'choice',
          itemsGetter: () => buildSortCandidates(fm.sortConfig),
        });
      },
    },
  ];

  return commands;
}

const deleteWithConfirmation = async (api: OrgNoteApi, paths: string[]): Promise<void> => {
  const confirmModal = api.ui.useConfirmationModal();
  const message = paths.length === 1 ? paths[0] : `${paths.length} files`;
  const confirmed = await confirmModal.confirm({
    title: I18N.CONFIRM_DELETE_FILE,
    message,
  });

  if (!confirmed) return;

  const fm = api.core.useFileManager();
  await fm.deleteFiles(paths);
};

