import { defineStore } from 'pinia';
import {
  ExtensionParsingError,
  type Extension,
  type ExtensionManifest,
  type ExtensionMeta,
  type ExtensionSource,
  type ExtensionSourceInfo,
  type ExtensionStore,
  type GitRepoHandle,
  type GitSource,
  type LocalSource,
} from 'orgnote-api';
import { ref, computed } from 'vue';
import { api } from 'src/boot/api';
import { extensionTimer } from 'src/boot/perf-timer';
import { compileExtension, parseExtensionFromFile } from 'src/utils/read-extension';
import { validateManifest } from 'src/utils/validate-manifest';
import { reporter } from 'src/boot/report';
import { to } from 'orgnote-api/utils';
import { useFileSystemStore } from './file-system';
import { parseToml, stringifyToml } from 'orgnote-api/utils';
import { useGitStore } from './git';
import { resetCSSVariables } from 'src/utils/css-utils';
import { THEME_VARIABLES } from 'orgnote-api';
import { useConfigStore } from './config';
import { Dark } from 'quasar';
import { ORGNOTE_EXTENSIONS_FILE_PATH } from 'src/constants/system-file-paths';
import { BUILTIN_LOADERS, BUILTIN_META } from 'src/extensions';

interface ActiveExtension extends ExtensionMeta {
  module: Extension;
}

interface ExtensionsFile {
  extensions: ExtensionMeta[];
}

interface FetchedExtension {
  manifest: ExtensionManifest;
  module: string;
  rawContent: string;
}

type SourceFetcher = (source: ExtensionSourceInfo) => Promise<FetchedExtension>;

const extensionsFilePath = ORGNOTE_EXTENSIONS_FILE_PATH;
const distFolder = 'dist';

export const useExtensionsStore = defineStore<'extension', ExtensionStore>('extension', () => {
  const extensions = ref<ExtensionMeta[]>([]);
  const activeExtensions = ref<ActiveExtension[]>([]);
  const fileSystem = useFileSystemStore();

  const loading = ref<number>(0);
  const ready = computed(() => loading.value <= 0);

  const safeParseToml = to(parseToml, (e) => new SyntaxError('Invalid TOML format', { cause: e }));
  const safeStringifyToml = to(
    stringifyToml,
    (e) => new Error('Failed to stringify TOML', { cause: e }),
  );

  const sync = async (): Promise<void> => {
    loading.value++;

    try {
      await extensionTimer.measure('sync', async () => {
        await readFromDisk();
        registerBuiltinExtensions();
        await mountActiveExtensions();
      });
    } finally {
      loading.value--;
    }
  };

  const registerBuiltinExtensions = (): void => {
    BUILTIN_META.forEach((meta) => {
      const exists = extensions.value.some((e) => e.manifest.name === meta.manifest.name);
      if (!exists) {
        extensions.value.push(meta);
      }
    });
  };

  const writeToDisk = async (): Promise<void> => {
    const data: ExtensionsFile = { extensions: extensions.value };
    const safeWrite = to(fileSystem.writeFile, 'Failed to write extensions.toml');

    const res = safeStringifyToml(data).asyncAndThen((content) =>
      safeWrite(extensionsFilePath, content),
    );

    const result = await res;
    if (result.isErr()) {
      reporter.reportError(result.error);
    }
  };

  const readFromDisk = async (): Promise<void> => {
    const safeRead = to(fileSystem.readFile, 'Failed to read extensions.toml');

    const res = await safeRead(extensionsFilePath, 'utf8');

    if (res.isErr()) {
      return;
    }

    const content = res.value;
    if (!content) {
      return;
    }

    const parseResult = safeParseToml(content as string);
    if (parseResult.isErr()) {
      reporter.reportError(parseResult.error);
      return;
    }

    const data = parseResult.value as unknown as ExtensionsFile;
    extensions.value = data.extensions ?? [];
  };

  const mountActiveExtensions = async (): Promise<void> => {
    const activeExtensionsMeta = extensions.value.filter((meta) => meta.active);

    const mountPromises = activeExtensionsMeta.map((meta) => mountExtension(meta));

    await Promise.allSettled(mountPromises);
  };

  const compileFromRepository = async (name: string): Promise<Extension | undefined> => {
    const source = await api.infrastructure.extensionSourceRepository.get(name);
    if (!source) {
      return undefined;
    }

    const safeCompile = to(compileExtension, 'Failed to load extension');
    const compileResult = await safeCompile(source.module);

    if (compileResult.isErr()) {
      reporter.reportError(compileResult.error);
      return undefined;
    }

    return compileResult.value;
  };

  const getExtensionModule = (name: string): Promise<Extension | undefined> =>
    BUILTIN_LOADERS[name]?.() ?? compileFromRepository(name);

  const mountExtension = async (meta: ExtensionMeta): Promise<ActiveExtension | undefined> => {
    return extensionTimer.measure(`mount:${meta.manifest.name}`, async () => {
      const existingActive = activeExtensions.value.find(
        (e) => e.manifest.name === meta.manifest.name,
      );
      if (existingActive) {
        return existingActive;
      }

      const module = await getExtensionModule(meta.manifest.name);
      if (!module) {
        return undefined;
      }

      const safeMounted = to(
        module.onMounted.bind(module),
        `Failed to mount extension ${meta.manifest.name}`,
      );
      const mountResult = await safeMounted(api);

      if (mountResult.isErr()) {
        reporter.reportError(mountResult.error);
        return undefined;
      }

      const activeExt: ActiveExtension = {
        manifest: meta.manifest,
        active: true,
        config: meta.config,
        module,
      };

      activeExtensions.value.push(activeExt);
      return activeExt;
    });
  };

  const unmountExtension = async (extensionName: string): Promise<void> => {
    return extensionTimer.measure(`unmount:${extensionName}`, async () => {
      const ext = activeExtensions.value.find((e) => e.manifest.name === extensionName);
      if (!ext) {
        return;
      }

      if (ext.module?.onUnmounted) {
        const safeUnmount = to(
          ext.module.onUnmounted.bind(ext.module),
          'Failed to unmount extension',
        );
        const result = await safeUnmount(api);

        if (result.isErr()) {
          reporter.reportError(result.error);
        }
      }

      activeExtensions.value = activeExtensions.value.filter(
        (e) => e.manifest.name !== extensionName,
      );
    });
  };

  const isThemeExtension = (manifest: ExtensionManifest): boolean => {
    return (manifest.category ?? '').toLowerCase() === 'theme';
  };

  const disableOtherThemes = async (currentThemeName: string): Promise<void> => {
    const otherActiveThemes = extensions.value.filter(
      (e) => e.active && isThemeExtension(e.manifest) && e.manifest.name !== currentThemeName,
    );

    const unmountPromises = otherActiveThemes.map(async (theme) => {
      await unmountExtension(theme.manifest.name);
      theme.active = false;
    });

    await Promise.allSettled(unmountPromises);
  };

  const setConfigThemeName = (themeName: string | null): void => {
    const { config } = useConfigStore();
    if (Dark.isActive) {
      config.ui.darkThemeName = themeName;
      return;
    }
    config.ui.lightThemeName = themeName;
  };

  const handleThemeActivation = async (extensionName: string): Promise<void> => {
    await disableOtherThemes(extensionName);
    resetCSSVariables([...THEME_VARIABLES]);
    setConfigThemeName(extensionName);
  };

  const handleThemeDeactivation = (extensionName: string): void => {
    const { config } = useConfigStore();
    const isCurrentDarkTheme = Dark.isActive && config.ui.darkThemeName === extensionName;
    const isCurrentLightTheme = !Dark.isActive && config.ui.lightThemeName === extensionName;
    if (!isCurrentDarkTheme && !isCurrentLightTheme) {
      return;
    }
    resetCSSVariables([...THEME_VARIABLES]);
    setConfigThemeName(null);
  };

  const enableExtension = async (extensionName: string): Promise<void> => {
    const meta = extensions.value.find((e) => e.manifest.name === extensionName);
    if (!meta) {
      reporter.reportWarning(`Extension ${extensionName} not found`);
      return;
    }

    if (meta.active) {
      return;
    }

    if (isThemeExtension(meta.manifest)) {
      await handleThemeActivation(extensionName);
    }

    await mountExtension(meta);
    meta.active = true;
    await writeToDisk();
  };

  const disableExtension = async (extensionName: string): Promise<void> => {
    const meta = extensions.value.find((e) => e.manifest.name === extensionName);
    if (!meta) {
      reporter.reportWarning(`Extension ${extensionName} not found`);
      return;
    }

    if (isThemeExtension(meta.manifest)) {
      handleThemeDeactivation(extensionName);
    }

    await unmountExtension(extensionName);
    meta.active = false;
    await writeToDisk();
  };

  const isExtensionExist = (extensionName: string): boolean => {
    return !!extensions.value.find((e) => e.manifest.name === extensionName);
  };

  const addExtension = async (meta: ExtensionMeta, source: ExtensionSource): Promise<void> => {
    extensions.value = extensions.value.filter((e) => e.manifest.name !== meta.manifest.name);
    extensions.value.push(meta);

    const safeUpsert = to(
      api.infrastructure.extensionSourceRepository.upsert,
      'Failed to save extension source',
    );
    const upsertResult = await safeUpsert(source);

    if (upsertResult.isErr()) {
      reporter.reportError(upsertResult.error);
      return;
    }

    await writeToDisk();

    if (meta.active) {
      await enableExtension(meta.manifest.name);
    }
  };

  const resolveExtensionPaths = async (
    repoHandle: GitRepoHandle,
  ): Promise<{ entryPath: string; manifestPath: string }> => {
    const hasDist = await repoHandle.fileExists(distFolder);
    const baseDir = hasDist ? `${distFolder}/` : '';
    return {
      entryPath: `${baseDir}index.js`,
      manifestPath: `${baseDir}manifest.json`,
    };
  };

  const extractManifestFromModule = async (moduleContent: string): Promise<ExtensionManifest> => {
    const encodedModule = encodeURIComponent(moduleContent);
    const moduleUrl = `data:text/javascript,${encodedModule}`;
    const m = (await import(/* @vite-ignore */ moduleUrl)) as {
      manifest?: ExtensionManifest;
    };

    if (!m.manifest) {
      throw new Error('Extension manifest not found in module exports');
    }

    return m.manifest;
  };

  const parseManifestJson = (content: string): ExtensionManifest => JSON.parse(content);

  const resolveManifest = async (
    repoHandle: GitRepoHandle,
    manifestPath: string,
    moduleContent: string,
  ): Promise<ExtensionManifest> => {
    const hasManifest = await repoHandle.fileExists(manifestPath);

    if (!hasManifest) {
      const manifest = await extractManifestFromModule(moduleContent);
      validateManifest(manifest);
      return manifest;
    }

    const content = await repoHandle.readFile(manifestPath, 'utf8');
    const safeParse = to(parseManifestJson, `Invalid manifest JSON in ${manifestPath}`);
    const parseResult = safeParse(content);

    if (parseResult.isErr()) {
      throw parseResult.error;
    }

    validateManifest(parseResult.value);
    return parseResult.value;
  };

  const fetchFromGit = async (source: GitSource): Promise<FetchedExtension> => {
    const gitStore = useGitStore();
    const repoHandle = await gitStore.openRepo({
      url: source.repo,
      branch: source.branch ?? source.tag,
    });

    const paths = await resolveExtensionPaths(repoHandle);
    const moduleContent = await repoHandle.readFile(paths.entryPath, 'utf8');
    const manifest = await resolveManifest(repoHandle, paths.manifestPath, moduleContent);
    manifest.source = source;

    return {
      manifest,
      module: encodeURIComponent(moduleContent),
      rawContent: moduleContent,
    };
  };

  const sourceFetchers: Record<ExtensionSourceInfo['type'], SourceFetcher> = {
    git: (source) => fetchFromGit(source as GitSource),
    local: () => {
      throw new Error('Local extensions cannot be installed via installExtension');
    },
    builtin: () => {
      throw new Error('Builtin extensions cannot be installed via installExtension');
    },
  };

  const installExtension = async (source: ExtensionSourceInfo): Promise<void> => {
    const fetcher = sourceFetchers[source.type];

    const safeFetch = to(fetcher, 'Failed to fetch extension');
    const fetchResult = await safeFetch(source);

    if (fetchResult.isErr()) {
      reporter.reportError(fetchResult.error);
      return;
    }

    const fetched = fetchResult.value;

    const meta: ExtensionMeta = {
      manifest: fetched.manifest,
      active: true,
    };

    const extensionSource: ExtensionSource = {
      name: fetched.manifest.name,
      version: fetched.manifest.version,
      source: source.type === 'git' ? (source as GitSource).repo : 'local',
      module: fetched.module,
      docFiles: [],
    };

    await addExtension(meta, extensionSource);
  };

  const deleteExtension = async (extensionName: string): Promise<void> => {
    await unmountExtension(extensionName);

    const safeDelete = to(
      api.infrastructure.extensionSourceRepository.delete,
      'Failed to delete extension source',
    );
    const deleteResult = await safeDelete(extensionName);

    if (deleteResult.isErr()) {
      reporter.reportError(deleteResult.error);
    }

    extensions.value = extensions.value.filter((e) => e.manifest.name !== extensionName);
    await writeToDisk();
  };

  const importExtension = async (file: File): Promise<void> => {
    const safeParse = to(parseExtensionFromFile, (e: unknown) => {
      const error = e instanceof Error ? e : new Error(String(e));
      return new ExtensionParsingError(file.name, { cause: error });
    });
    const parseResult = await safeParse(file);

    if (parseResult.isErr()) {
      reporter.reportError(parseResult.error);
      return;
    }

    const { manifest, rawContent } = parseResult.value;

    const localSource: LocalSource = { type: 'local' };
    manifest.source = localSource;
    manifest.development = true;

    const meta: ExtensionMeta = {
      manifest,
      active: true,
      uploaded: true,
    };

    const extensionSource: ExtensionSource = {
      name: manifest.name,
      version: manifest.version,
      source: 'local',
      module: rawContent,
      docFiles: [],
    };

    await addExtension(meta, extensionSource);
  };

  const enableSafeMode = async (): Promise<void> => {
    const nonLocalExtensions = activeExtensions.value.filter(
      (ext) => ext.manifest.source.type !== 'local',
    );

    const unmountPromises = nonLocalExtensions.map((ext) => unmountExtension(ext.manifest.name));
    await Promise.allSettled(unmountPromises);
  };

  const disableSafeMode = async (): Promise<void> => {
    const activeExtensionsMeta = extensions.value.filter((meta) => meta.active);
    const mountPromises = activeExtensionsMeta.map((meta) => mountExtension(meta));
    await Promise.allSettled(mountPromises);
  };

  const store: ExtensionStore = {
    extensions,
    ready,

    sync,
    enableExtension,
    disableExtension,
    isExtensionExist,
    addExtension,
    installExtension,
    importExtension,
    deleteExtension,
    enableSafeMode,
    disableSafeMode,
  };

  return store;
});

import { ref, type Ref } from 'vue';

export interface PerfMeasurement {
  readonly name: string;
  readonly scope: string;
  readonly duration: number;
  readonly startTime: number;
}

export interface PerfReport {
  readonly measurements: readonly PerfMeasurement[];
  readonly totalDuration: number;
  readonly generatedAt: Date;
}

export interface NavigationPhase {
  readonly name: string;
  readonly duration: number;
  readonly startTime: number;
}

export interface PaintEntry {
  readonly name: string;
  readonly startTime: number;
}

export interface ResourceEntry {
  readonly name: string;
  readonly type: string;
  readonly size: number;
  readonly duration: number;
  readonly startTime: number;
}

export interface BrowserTimingReport {
  readonly navigation: readonly NavigationPhase[];
  readonly paint: readonly PaintEntry[];
  readonly resources: readonly ResourceEntry[];
}

type PerfEntry = { startTime: number; scope: string; label: string };

const SCOPE_SEPARATOR = ':';
const MARK_START_SUFFIX = ':start';
const MARK_END_SUFFIX = ':end';
const NAMESPACE = 'orgnote';
const MAX_MEASUREMENTS = 500;
const IS_CLIENT = typeof window !== 'undefined';

const pendingStarts = new Map<string, PerfEntry>();
const completedMeasurements: PerfMeasurement[] = [];
let activeObserver: PerformanceObserver | null = null;

export const reportVersion: Ref<number> = ref(0);

const buildKey = (scope: string, label: string): string =>
  `${scope}${SCOPE_SEPARATOR}${label}`;

const buildMarkName = (key: string, suffix: string): string =>
  `${NAMESPACE}${SCOPE_SEPARATOR}${key}${suffix}`;

const buildMeasureName = (key: string): string =>
  `${NAMESPACE}${SCOPE_SEPARATOR}${key}`;

const bumpVersion = (): void => {
  reportVersion.value++;
};

const recordMeasurement = (entry: PerfEntry, duration: number): void => {
  completedMeasurements.push({
    name: entry.label,
    scope: entry.scope,
    duration,
    startTime: entry.startTime,
  });

  if (completedMeasurements.length > MAX_MEASUREMENTS) {
    completedMeasurements.splice(
      0,
      completedMeasurements.length - MAX_MEASUREMENTS,
    );
  }

  bumpVersion();
};

export interface ScopedTimer {
  readonly scope: string;
  start: (label: string) => void;
  end: (label: string) => number;
  measure: <T>(label: string, fn: () => T | Promise<T>) => Promise<T>;
  report: () => PerfReport;
}

const createNoOpTimer = (scope: string): ScopedTimer => ({
  scope,
  start: () => {},
  end: () => 0,
  measure: async <T>(_label: string, fn: () => T | Promise<T>) => fn(),
  report: () => ({ measurements: [], totalDuration: 0, generatedAt: new Date() }),
});

export const createPerfTimer = (scope: string): ScopedTimer => {
  if (!IS_CLIENT) return createNoOpTimer(scope);

  const scopedStart = (label: string): void => {
    const key = buildKey(scope, label);
    const startTime = performance.now();
    const startMark = buildMarkName(key, MARK_START_SUFFIX);

    if (pendingStarts.has(key) && process.env.DEV) {
      console.warn(
        `[perf-timer] Overwriting pending start for "${key}". Concurrent measurements with the same label are not supported.`,
      );
    }

    performance.mark(startMark);
    pendingStarts.set(key, { startTime, scope, label });
  };

  const scopedEnd = (label: string): number => {
    const key = buildKey(scope, label);
    const entry = pendingStarts.get(key);

    if (!entry) {
      if (process.env.DEV) {
        console.warn(
          `[perf-timer] end() called without matching start() for "${key}"`,
        );
      }
      return 0;
    }

    const endTime = performance.now();
    const startMark = buildMarkName(key, MARK_START_SUFFIX);
    const endMark = buildMarkName(key, MARK_END_SUFFIX);
    const measureName = buildMeasureName(key);

    performance.mark(endMark);

    try {
      performance.measure(measureName, startMark, endMark);
    } catch (e) {
      if (process.env.DEV) {
        console.warn(`[perf-timer] measure failed for ${measureName}:`, e);
      }
    }

    performance.clearMarks(startMark);
    performance.clearMarks(endMark);
    performance.clearMeasures(measureName);

    pendingStarts.delete(key);
    const duration = endTime - entry.startTime;
    recordMeasurement(entry, duration);

    return duration;
  };

  const scopedMeasure = async <T>(
    label: string,
    fn: () => T | Promise<T>,
  ): Promise<T> => {
    scopedStart(label);

    try {
      return await fn();
    } finally {
      scopedEnd(label);
    }
  };

  const scopedReport = (): PerfReport => {
    const scoped = completedMeasurements.filter((m) => m.scope === scope);
    const totalDuration = scoped.reduce((sum, m) => sum + m.duration, 0);

    return {
      measurements: scoped,
      totalDuration,
      generatedAt: new Date(),
    };
  };

  return {
    scope,
    start: scopedStart,
    end: scopedEnd,
    measure: scopedMeasure,
    report: scopedReport,
  };
};

const extractPhase = (
  nav: PerformanceNavigationTiming,
  name: string,
  start: keyof PerformanceNavigationTiming,
  end: keyof PerformanceNavigationTiming,
): NavigationPhase => ({
  name,
  startTime: Number(nav[start]),
  duration: Number(nav[end]) - Number(nav[start]),
});

const RESOURCE_TYPE_MAP: Record<string, string> = {
  script: 'JS',
  link: 'CSS',
  img: 'Image',
  xmlhttprequest: 'XHR',
  fetch: 'Fetch',
};

const MAX_RESOURCES = 20;

export const getBrowserTimingReport = (): BrowserTimingReport => {
  if (!IS_CLIENT) return { navigation: [], paint: [], resources: [] };

  const nav = performance.getEntriesByType('navigation')[0] as
    | PerformanceNavigationTiming
    | undefined;

  const navigation: NavigationPhase[] = nav
    ? [
        extractPhase(nav, 'DNS Lookup', 'domainLookupStart', 'domainLookupEnd'),
        extractPhase(nav, 'TCP/TLS', 'connectStart', 'connectEnd'),
        extractPhase(nav, 'Request', 'requestStart', 'responseStart'),
        extractPhase(nav, 'Download', 'responseStart', 'responseEnd'),
        extractPhase(nav, 'DOM Parse', 'domInteractive', 'domComplete'),
        extractPhase(nav, 'Load Event', 'loadEventStart', 'loadEventEnd'),
      ]
    : [];

  const paint: PaintEntry[] = performance
    .getEntriesByType('paint')
    .map((e) => ({ name: e.name, startTime: e.startTime }));

  const resources: ResourceEntry[] = performance
    .getEntriesByType('resource')
    .map((e) => e as PerformanceResourceTiming)
    .filter((e) => e.transferSize > 0)
    .sort((a, b) => b.duration - a.duration)
    .slice(0, MAX_RESOURCES)
    .map((e) => ({
      name: e.name.split('/').pop() ?? e.name,
      type: RESOURCE_TYPE_MAP[e.initiatorType] ?? e.initiatorType,
      size: e.transferSize,
      duration: e.duration,
      startTime: e.startTime,
    }));

  return { navigation, paint, resources };
};

export const getFullReport = (): PerfReport => {
  const totalDuration = completedMeasurements.reduce(
    (sum, m) => sum + m.duration,
    0,
  );

  return {
    measurements: [...completedMeasurements],
    totalDuration,
    generatedAt: new Date(),
  };
};

export const getScopeReport = (scope: string): PerfReport => {
  const scoped = completedMeasurements.filter((m) => m.scope === scope);
  const totalDuration = scoped.reduce((sum, m) => sum + m.duration, 0);

  return {
    measurements: scoped,
    totalDuration,
    generatedAt: new Date(),
  };
};

export const clearAllMeasurements = (): void => {
  completedMeasurements.length = 0;
  pendingStarts.clear();

  performance.getEntriesByType('mark').forEach((entry) => {
    if (entry.name.startsWith(NAMESPACE)) {
      performance.clearMarks(entry.name);
    }
  });

  performance.getEntriesByType('measure').forEach((entry) => {
    if (entry.name.startsWith(NAMESPACE)) {
      performance.clearMeasures(entry.name);
    }
  });

  bumpVersion();
};

export const disconnectObserver = (): void => {
  if (activeObserver) {
    activeObserver.disconnect();
    activeObserver = null;
  }
};

export const BOOT_SCOPE = 'boot';
export const EXTENSION_SCOPE = 'ext';
export const RUNTIME_SCOPE = 'runtime';

export const bootTimer = createPerfTimer(BOOT_SCOPE);
export const extensionTimer = createPerfTimer(EXTENSION_SCOPE);
export const runtimeTimer = createPerfTimer(RUNTIME_SCOPE);

export const setupPerformanceObserver = (
  onMeasure?: (measurement: PerfMeasurement) => void,
): PerformanceObserver | null => {
  if (!IS_CLIENT) return null;

  disconnectObserver();

  const observer = new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (!entry.name.startsWith(NAMESPACE)) continue;

      const found = completedMeasurements.find(
        (m) => entry.name === buildMeasureName(buildKey(m.scope, m.name)),
      );

      if (found && onMeasure) {
        onMeasure(found);
      }
    }
  });

  observer.observe({ type: 'measure', buffered: true });
  activeObserver = observer;
  return observer;
};

export const logReportToConsole = (scope?: string): void => {
  if (!IS_CLIENT) return;

  const report = scope ? getScopeReport(scope) : getFullReport();
  const browser = getBrowserTimingReport();

  const sorted = [...report.measurements].sort(
    (a, b) => a.startTime - b.startTime,
  );

  console.group('[OrgNote] Performance Report');

  if (browser.navigation.length) {
    console.group('Network');
    browser.navigation.forEach((p) =>
      console.log(`${p.name}: ${p.duration.toFixed(1)}ms`),
    );
    console.groupEnd();
  }

  browser.paint.forEach((p) =>
    console.log(`${p.name}: ${p.startTime.toFixed(1)}ms`),
  );

  console.group('Boot');
  sorted.forEach((m) =>
    console.log(`[${m.scope}] ${m.name}: ${m.duration.toFixed(1)}ms`),
  );
  console.groupEnd();

  console.groupEnd();
};

import type { Command, CommandHandlerParams, OrgNoteApi } from 'orgnote-api';
import { DefaultCommands, I18N } from 'orgnote-api';
import { api } from 'src/boot/api';
import { defineAsyncComponent } from 'vue';
import { uploadFile } from 'src/utils/file-upload';

import { getHostRelatedPath } from 'src/utils/get-host-related-path';
import { selectCommand } from 'src/utils/select-command';
import { clearAllMeasurements } from 'src/boot/perf-timer';

export function getDeveloperCommands(): Command[] {
  const openQueueManager = () => {
    const modal = api.ui.useModal();
    modal.open(
      defineAsyncComponent(() => import('src/containers/QueueManager.vue')),
      {
        title: 'Queue Manager',
        closable: true,
        wide: true,
      },
    );
  };

  const openCronManager = () => {
    const modal = api.ui.useModal();
    modal.open(
      defineAsyncComponent(() => import('src/containers/CronManager.vue')),
      {
        title: 'Cron Manager',
        closable: true,
        wide: true,
      },
    );
  };

  const commands: Command[] = [
    {
      command: DefaultCommands.OPEN_QUEUE_MANAGER,
      handler: openQueueManager,
      hide: (api: OrgNoteApi) => {
        const config = api.core.useConfig();
        return !config.config.developer.developerMode;
      },
      icon: 'sym_o_queue',
      group: 'developer',
    },

    {
      command: DefaultCommands.RESTART_QUEUE,
      group: 'developer',
      icon: 'sym_o_play_arrow',
      description: 'Restart (resume) queue processing',
      handler: (
        api,
        params: CommandHandlerParams<{
          queueId?: string;
        }>,
      ) => {
        const queueId = params?.queueId as string | undefined;
        api.core.useQueue().resume(queueId ?? 'default');
        api.ui.useModal().close();
      },
    },
    {
      command: DefaultCommands.STOP_QUEUE,
      group: 'developer',
      icon: 'sym_o_pause',
      description: 'Stop (pause) queue processing',
      handler: (
        api,
        params: CommandHandlerParams<{
          queueId?: string;
        }>,
      ) => {
        const queueId = params?.queueId as string | undefined;
        api.core.useQueue().pause(queueId ?? 'default');
        api.ui.useModal().close();
      },
    },
    {
      command: DefaultCommands.CLEAR_QUEUE,
      group: 'developer',
      icon: 'sym_o_delete_sweep',
      description: 'Clear all tasks from queue',
      handler: async (
        api,
        params: CommandHandlerParams<{
          queueId?: string;
        }>,
      ) => {
        const queueId = params?.queueId as string | undefined;
        await api.core.useQueue().clear(queueId ?? 'default');
        api.ui.useModal().close();
      },
    },
    {
      command: DefaultCommands.OPEN_CRON,
      handler: openCronManager,
      hide: (api: OrgNoteApi) => {
        const config = api.core.useConfig();
        return !config.config.developer.developerMode;
      },
      icon: 'sym_o_schedule',
      group: 'developer',
    },
    {
      command: DefaultCommands.CLEAR_OLD_QUEUE_TASKS,
      handler: async (api: OrgNoteApi) => {
        const queueRepository = api.infrastructure.queueRepository;
        const tasks = await queueRepository.getAll();
        const m = api.core.useConfig().config.developer.storeQueueTasksMinutes;

        const cutoffTime = Date.now() - m * 60 * 1000;
        const oldQueueTasks = tasks.filter((t) => (t.added ?? 0) < cutoffTime);

        if (!oldQueueTasks.length) {
          return;
        }

        await Promise.all(oldQueueTasks.map((t) => queueRepository.delete(t.id, true)));

        api.utils.logger.info(`Cleared ${oldQueueTasks.length} old queue tasks.`);
      },
      hide: (api: OrgNoteApi) => {
        const config = api.core.useConfig();
        return !config.config.developer.developerMode;
      },
      icon: 'sym_o_schedule',
      group: 'developer',
    },
    {
      command: DefaultCommands.IMPORT_EXTENSION,
      handler: async (api: OrgNoteApi) => {
        const file = await uploadFile({ accept: '.js' });
        if (!file) {
          return;
        }
        await api.core.useExtensions().importExtension(file);
      },
      hide: (api: OrgNoteApi) => {
        const config = api.core.useConfig();
        return !config.config.developer.developerMode;
      },
      icon: 'sym_o_upload',
      group: 'developer',
    },
    {
      command: DefaultCommands.COPY_COMMAND_URL,
      handler: async (api: OrgNoteApi) => {
        const command = await selectCommand(api, I18N.SELECT_COMMAND_TO_COPY_URL);

        if (!command) {
          return;
        }

        const searchParams = new URLSearchParams();
        searchParams.set('execute', JSON.stringify({ command: command.command }));
        const url = getHostRelatedPath(`?${searchParams.toString()}`);

        await api.utils.copyToClipboard(url);
        api.core.useNotifications().notify({
          message: I18N.COPIED_TO_CLIPBOARD,
          level: 'info',
        });
      },
      icon: 'sym_o_link',
      hide: (api: OrgNoteApi) => {
        const config = api.core.useConfig();
        return !config.config.developer.developerMode;
      },
    },
    {
      command: DefaultCommands.SHOW_PERFORMANCE_REPORT,
      title: I18N.SHOW_PERFORMANCE_REPORT,
      description: I18N.SHOW_PERFORMANCE_REPORT_DESCRIPTION,
      icon: 'sym_o_speed',
      group: 'developer',
      hide: (api: OrgNoteApi) => !api.core.useConfig().config.developer.developerMode,
      handler: async (api: OrgNoteApi) => {
        const modal = api.ui.useModal();
        modal.open(
          defineAsyncComponent(() => import('src/containers/PerformanceReportContainer.vue')),
          { title: I18N.SHOW_PERFORMANCE_REPORT, closable: true },
        );
      },
    },
    {
      command: DefaultCommands.CLEAR_PERFORMANCE_REPORT,
      title: I18N.CLEAR_PERFORMANCE_REPORT,
      description: I18N.CLEAR_PERFORMANCE_REPORT_DESCRIPTION,
      icon: 'sym_o_delete_sweep',
      group: 'developer',
      hide: (api: OrgNoteApi) => !api.core.useConfig().config.developer.developerMode,
      handler: async (api: OrgNoteApi) => {
        clearAllMeasurements();
        api.core.useNotifications().notify({
          message: I18N.CLEAR_PERFORMANCE_REPORT,
          level: 'info',
        });
      },
    },
    {
      command: 'seed-demo-notes',
      title: 'Seed demo notes',
      description: 'Generate 600 seeded notes with tags, links, and varied org content',
      icon: 'sym_o_hub',
      group: 'developer',
      hide: (api: OrgNoteApi) => !api.core.useConfig().config.developer.developerMode,
      handler: async (api: OrgNoteApi) => {
        const { seedDemoNotes } = await import('src/commands/seed-demo-notes');
